<title>Noir Studio | Product Photography & Videography</title>
<style>
:root{--bg:#080908;--panel:#11120f;--gold:#d7ad61;--light:#f7f2e8;--muted:#bcb7aa;--line:#453a28}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--light);font:15px/1.65 Arial,sans-serif}a{color:inherit;text-decoration:none}.wrap{width:min(1160px,91%);margin:auto}.topbar{padding:7px 0;background:#040504;color:#d6c49d;font-size:11px;letter-spacing:.5px}.topbar .wrap{display:flex;justify-content:space-between}header{position:sticky;top:0;z-index:5;background:#080908f5;border-bottom:1px solid #514124}.nav{height:74px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{font:24px Georgia,serif;letter-spacing:1px}.logo small{display:block;text-align:center;font:9px Arial;letter-spacing:3px;color:var(--gold)}.links{display:flex;gap:24px;font-size:13px}.links a:hover{color:var(--gold)}.btn{display:inline-block;border-radius:40px;padding:11px 20px;font-size:13px;font-weight:bold;border:1px solid #b6a37e}.gold{background:var(--gold);color:#17130b;border-color:var(--gold)}.outline{background:transparent;color:white}.menu{display:none;background:transparent;color:var(--gold);border:1px solid var(--line);padding:8px}.hero{min-height:500px;display:flex;align-items:center;background:linear-gradient(90deg,#050605 0%,#050605df 38%,#05060515 100%),url('https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=1800&q=85') center/cover;border-bottom:1px solid #514124}.hero-inner{padding:65px 0;max-width:570px}.eyebrow{font-size:10px;color:var(--gold);font-weight:bold;letter-spacing:2px;text-transform:uppercase}.hero h1,.heading{font:400 clamp(36px,5vw,67px)/1.08 Georgia,serif;letter-spacing:-1px;margin:16px 0}.hero h1 em{color:#f0ce8a}.hero p,.copy{color:var(--muted);max-width:480px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}.services{padding:26px 0;background:#0d0e0c;border-bottom:1px solid var(--line)}.service-grid{display:grid;grid-template-columns:repeat(5,1fr)}.service{text-align:center;padding:12px;border-right:1px solid #373229}.service:last-child{border:0}.symbol{font-size:27px;color:var(--gold)}.service h3{font:16px Georgia,serif;color:#f0ce8a;margin:6px}.service p{font-size:12px;color:var(--muted);margin:0}.section{padding:70px 0}.heading{font-size:clamp(32px,4vw,47px);margin:10px 0 15px}.portfolio-head{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:25px}.portfolio-head p{max-width:360px;color:var(--muted);font-size:14px}.works{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.work img{width:100%;height:205px;object-fit:cover;border:1px solid var(--line);display:block;transition:.2s}.work:hover img{transform:translateY(-3px)}.work h3{font:17px Georgia,serif;color:#f0ce8a;margin:9px 0 0}.work p{font-size:12px;color:var(--muted);margin:0}.about{background:radial-gradient(ellipse at left,#21190e,#090a08 55%);border-block:1px solid var(--line)}.about-grid{display:grid;grid-template-columns:1fr 1.1fr .55fr;gap:32px;align-items:center}.photos{display:grid;grid-template-columns:1.1fr .9fr;gap:9px;align-items:center}.photos img{width:100%;height:240px;object-fit:cover;border:1px solid var(--line)}.photos img+img{height:195px}.stats{border-left:1px solid var(--line);padding-left:22px}.stat{margin:12px 0}.stat strong{display:block;color:var(--gold);font:29px Georgia,serif}.stat span{font-size:12px;color:var(--muted)}.faq{border-bottom:1px solid var(--line)}.faq-grid{display:grid;grid-template-columns:.75fr 1.2fr;gap:55px}.faq-list details{border:1px solid #302d25;background:#11120f;margin-bottom:8px;border-radius:4px}.faq-list summary{cursor:pointer;list-style:none;padding:14px 16px;display:flex;justify-content:space-between;gap:15px;font-size:14px}.faq-list summary::-webkit-details-marker{display:none}.faq-list summary:after{content:'+';color:var(--gold);font-size:18px}.faq-list details[open] summary:after{content:'−'}.faq-list details p{padding:0 16px 15px;margin:0;color:var(--muted);font-size:13px}.contact{background:#10110f}.contact-grid{display:grid;grid-template-columns:.8fr 1.2fr .9fr;gap:18px}.contact-list{font-size:13px;color:var(--muted)}.contact-list p{margin:11px 0}.contact-list b{color:var(--gold);font-weight:normal}.map{width:100%;height:100%;min-height:260px;border:1px solid var(--line);filter:grayscale(.25)}.studio{border:1px solid var(--line);padding:12px}.studio img{width:100%;height:130px;object-fit:cover}.studio h3{font:22px Georgia,serif;color:#f0ce8a;margin:8px 0 0}.studio p{font-size:12px;color:var(--muted)}footer{padding:25px 0;background:#040504;border-top:1px solid var(--line)}.footer-row{display:flex;align-items:center;justify-content:space-between;gap:20px}.footer-links{display:flex;gap:17px;font-size:12px}.social{color:var(--gold);letter-spacing:5px}.copyright{border-top:1px solid #28251f;margin-top:18px;padding-top:12px;display:flex;justify-content:space-between;color:#8f897d;font-size:11px}.floating{position:fixed;right:16px;bottom:18px;z-index:8;display:flex;flex-direction:column;gap:9px}.float{border:1px solid #6c542a;border-radius:40px;padding:11px 15px;font-size:12px;font-weight:bold;box-shadow:0 5px 20px #0008}.ai{background:#171813;color:#f0ce8a}.wa{background:#0d8b66;color:white;border-color:#0d8b66}.chat{display:none;position:fixed;z-index:9;right:20px;bottom:132px;width:min(320px,calc(100vw - 40px));background:#11120f;border:1px solid #6a522b;border-radius:9px;overflow:hidden}.chat.active{display:block}.chat-head{padding:12px;background:#292113;color:#f0ce8a;display:flex;justify-content:space-between}.chat-body{padding:15px;color:var(--muted);font-size:13px}.chat input{width:100%;padding:10px;background:#080908;border:1px solid var(--line);color:white;margin:8px 0}.chat button{background:var(--gold);border:0;padding:9px 12px;border-radius:4px}
@media(max-width:850px){.links{display:none;position:absolute;top:74px;left:0;right:0;background:#080908;padding:18px 5%;flex-direction:column}.links.open{display:flex}.menu{display:block}.nav>.btn{display:none}.service-grid{grid-template-columns:repeat(3,1fr)}.service{border-bottom:1px solid var(--line)}.about-grid{grid-template-columns:1fr 1fr}.stats{grid-column:span 2;display:flex;justify-content:space-between;border:0;border-top:1px solid var(--line);padding:15px 0}.contact-grid{grid-template-columns:1fr 1fr}.studio{grid-column:span 2}.faq-grid{gap:25px}}
@media(max-width:560px){.topbar .wrap span+span{display:none}.nav{height:66px}.links{top:66px}.logo{font-size:21px}.hero{min-height:490px;background-position:62% center}.hero h1{font-size:43px}.section{padding:50px 0}.service-grid{grid-template-columns:1fr 1fr}.service{padding:12px 7px}.portfolio-head{display:block}.works{grid-template-columns:1fr 1fr;gap:11px}.work img{height:155px}.about-grid,.faq-grid,.contact-grid{grid-template-columns:1fr}.photos img{height:200px}.photos img+img{height:165px}.stats{grid-column:auto}.studio{grid-column:auto}.map{height:260px}.footer-row{align-items:flex-start;flex-direction:column}.footer-links{flex-wrap:wrap}.copyright{flex-direction:column;gap:5px}.floating{right:9px;bottom:10px}}
</style>
