<div class="chat" id="chat"><div class="chat-head">Noir AI Assistant <button id="close" style="background:none;color:#f0ce8a;border:0">×</button></div><div class="chat-body"><p>Halo! Ada yang ingin ditanyakan tentang foto produk atau video promosi?</p><input id="question" placeholder="Tulis pertanyaan Anda..."><button id="send">Kirim pertanyaan</button><p id="reply" aria-live="polite"></p></div></div>
<script>
const links=document.getElementById('links');document.getElementById('menu').onclick=()=>links.classList.toggle('open');links.querySelectorAll('a').forEach(a=>a.onclick=()=>links.classList.remove('open'));const chat=document.getElementById('chat');document.getElementById('ai').onclick=()=>chat.classList.toggle('active');document.getElementById('close').onclick=()=>chat.classList.remove('active');document.getElementById('send').onclick=()=>{const q=document.getElementById('question').value.trim();document.getElementById('reply').textContent=q?'Terima kasih! Untuk harga dan jadwal, silakan lanjutkan konsultasi melalui WhatsApp.':'Silakan tulis pertanyaan terlebih dahulu.'};
</script>
